// Adds corresponding elements from two vectors using std::transform
// with the binary overload. The result is written into the output vector.
std::vector<int> add_pairwise(const std::vector<int>& a, const std::vector<int>& b) {
    std::vector<int> out(a.size());
    std::transform(a.begin(), a.end(), b.begin(), out.begin(),
