    assert(sem.try_acquire());
    assert(!sem.try_acquire()); // count is 0

    sem.release();
    assert(sem.try_acquire());

    std::string desc = describe_counting_semaphore();
    assert(!desc.empty());

    std::cout << "All tests passed." << std::endl;
